// "ShaderToy Tutorial - Ray Marching Operators 2" 
// by Martijn Steinrucken aka BigWings/CountFrolic - 2019
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.
// 
// This is the starting point for a YouTube tutorial:
// https://youtu.be/Vmb7VGBVZJA

#define MAX_STEPS 200
#define MAX_DIST 100.
#define SURF_DIST .001

#define C 10.
#define BOXSPEED 5.

#define PI 3.14159

vec4 GetDist(vec3 p, float t) {
    float plane = p.y;

    // d(cos(t)*10)/dt
    vec3 v = vec3(-sin(t)*BOXSPEED, 0, 0);
    float box = sdBox(p-vec3(cos(t)*BOXSPEED, 1, -3), vec3(1));

    float rotationalSpeed = 0.7;
    float rotational = rotationalSpeed * t * PI * 2.;
    vec3 rbp = p-vec3(0,1,0);
         rbp.xz *= Rot(rotational);
    float rotatingBox = sdBox(rbp, vec3(1));

    float speedBoxSpeed = C * 0.99;
    float speedBox = sdBox(p - vec3(C * 10. - speedBoxSpeed * t, 3, -5), vec3(1));

    //The plane is not moving
    if(plane < box) v = vec3(0);

    //The rotating box is only moving rotationally, so we calculate it by revs * r
    if(rotatingBox < plane && rotatingBox < box) { float _ = rotationalSpeed * 1.;
                            v = vec3(sin(rotational) * _, 0, cos(rotational) * _); }

    if(speedBox < rotatingBox) vec3(speedBoxSpeed, 0., 0.);

    float d = min(plane, box);
          d = min(d, rotatingBox);
          d = min(d, speedBox);
    return vec4(d, v);
}

vec2 RayMarch(vec3 ro, vec3 rd, float t) {
	float dO = 0.;

    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p, t).x / 2.;
        dO += dS;
        if(iMouse.z < .5) t -= dS / C;
        if(dO>MAX_DIST || dS<SURF_DIST) break;
    }

    return vec2(dO, t);
}

vec3 GetNormal(vec3 p, float t) {
	float d = GetDist(p, t).x;
    vec2 e = vec2(.001, 0);

    vec3 n = d - vec3(
        GetDist(p-e.xyy, t).x,
        GetDist(p-e.yxy, t).x,
        GetDist(p-e.yyx, t).x);

    return normalize(n);
}

float GetLight(vec3 p, float t) {
    vec3 lightPos = vec3(3, 5, 4);
    vec3 l = normalize(lightPos-p);
    vec3 n = GetNormal(p, t);

    float dif = clamp(dot(n, l)*.5+.5, 0., 1.);
    float d = RayMarch(p+n*SURF_DIST*2., l, t).x;
   // if(p.y<.01 && d<length(lightPos-p)) dif *= .5;

    return dif;
}

vec3 R(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = p+f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i-p);
    return d;
}

vec3 light(float l) {
    vec3 i = vec3(0);
    for(float w=400.;w<800.;w+=400./1.) {
        i += spectral_zucconi(w * l);
    }
    return i / 20.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
	vec2 m = iMouse.xy/iResolution.xy;

    vec3 col = vec3(0);

    vec3 ro = vec3(0., 4, -5);
    ro.yz *= Rot(-m.y*3.14+1.);
    ro.xz *= Rot(-m.x*6.2831);

    vec3 v = vec3(cos(iTime), 0., 0.);

    vec3 rd = R(uv, ro, vec3(0,1,0), 1.);

    vec2 r = RayMarch(ro, rd, iTime);
    float d = r.x;
    float t = r.y;

    if(d<MAX_DIST) {
    	vec3 p = ro + rd * d;

    	float dif = GetLight(p, t);
    	col = vec3(dif);

        vec3 vreal = v - GetDist(p, t).yzw;
        float v = length(vreal);
        float l = length(1. / sqrt(1. - ((v * v) / (C * C))));

        if(iMouse.z > .5) l = 1.;
        col *= spectral_zucconi(550.*l);
    }
    col = pow(col, vec3(.4545));	// gamma correction

    fragColor = vec4(col,1.0);
}

